BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8636c7baf7b9441624e26d44023cae263c6bd03f/content/books/zizhi-tongjian/vol-287/year-0947/part-05/sources/library/jiuwudaishi-100-august-hengzhou/source.txt", "note": "《旧五代史》卷一百，段落 jiu-wudaishi-205deb4a7860-p002438；EPUB电子本，纸本及异文待核", "id": "9542df20-d802-5e42-8f7d-6fb9494c72f6"}, {"title": "旧五代史·卷一百", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8636c7baf7b9441624e26d44023cae263c6bd03f/content/books/zizhi-tongjian/vol-287/year-0947/part-05/sources/library/jiuwudaishi-100-intercalary-july/source.txt", "note": "《旧五代史》卷一百，段落 jiu-wudaishi-205deb4a7860-p002437；EPUB电子本，纸本及异文待核", "id": "bb6c1ffe-8ba0-5ccd-992a-49cc63adf0dc"}, {"title": "旧五代史·卷一百〇六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8636c7baf7b9441624e26d44023cae263c6bd03f/content/books/zizhi-tongjian/vol-287/year-0947/part-05/sources/library/jiuwudaishi-106-bai-zairong/source.txt", "note": "《旧五代史》卷一百〇六，段落 jiu-wudaishi-205deb4a7860-p002546；EPUB电子本，纸本及异文待核", "id": "0e8c5cbe-b3b5-5150-874d-9f7f18041aa1"}, {"title": "宋史·巻四百八十四", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8636c7baf7b9441624e26d44023cae263c6bd03f/content/books/zizhi-tongjian/vol-287/year-0947/part-05/sources/library/songshi-484-li-yun-name/source.txt", "note": "《宋史》巻四百八十四，段落 songshi-9c6e46fee832-p075283；EPUB电子本，纸本及异文待核", "id": "1f2dd369-b973-574c-bce6-0a4fcdd904fc"}, {"title": "宋史·巻四百八十四", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8636c7baf7b9441624e26d44023cae263c6bd03f/content/books/zizhi-tongjian/vol-287/year-0947/part-05/sources/library/songshi-484-li-yun-origin/source.txt", "note": "《宋史》巻四百八十四，段落 songshi-9c6e46fee832-p075274；EPUB电子本，纸本及异文待核", "id": "830d825d-f25b-5032-a9e9-8598d52a9df7"}, {"title": "资治通鉴·后汉纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8636c7baf7b9441624e26d44023cae263c6bd03f/content/books/zizhi-tongjian/vol-287/year-0947/part-05/sources/library/tongjian-287-947-hengzhou-uprising/source.txt", "note": "《资治通鉴》后汉纪二，段落 zizhi-tongjian-a63549944a71-p003408；电子底本待考，分段待核", "id": "6a26cc69-9fa5-5783-93b7-06d09e929731"}, {"title": "资治通鉴·后汉纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/44b0593aeab837b5fbc1263a74f880f3ba1b4acb/content/books/zizhi-tongjian/vol-287/year-0947/part-04/sources/library/tongjian-287-947-june-july-governors/source.txt", "note": "《资治通鉴》后汉纪二，段落 zizhi-tongjian-a63549944a71-p003407；电子底本待考，分段待核", "id": "5595ed79-f507-5f3b-863b-dfbb9293440f"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李仁达", "aliases": ["李仁達", "李弘义", "李弘義", "李弘达", "李弘達", "李宏达", "李宏達", "李达", "李達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "光州人，曾任闽元从指挥使，多次在建州、福州之间投奔不同执政者。945年与陈继珣、黄仁讽发动福州政变，杀王继昌和吴成义，拥立僧卓岩明。后来又杀黄仁讽、陈继珣，将福州兵权集中到自己手中。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "97ca7dea-54b1-5a38-a747-3dc803037d55"}, {"name": "李通（李仁达弟）", "aliases": ["李通（李仁達弟）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李仁达的弟弟。947年李仁达赴钱唐见吴越王钱弘倧时，令他在福州代理留后事务。生卒年未载。", "biography": null, "status": "draft", "id": "695b9e7b-0e6f-5772-9f23-ec671541cb51"}, {"name": "钱弘倧", "aliases": ["錢弘倧"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲鹿氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "141c421e-2a7d-5b59-91f9-bf5ec3f726df"}, {"name": "胡进思", "aliases": ["胡進思"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "湖州人，吴越右统军使。943年条下记章德安与李文庆被贬后，史书称他与阚璠更加专横。生卒年尚未核。", "biography": null, "status": "draft", "id": "4f56160f-2b15-5a0c-9fa8-9523947bb1df"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "杜弘璲", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杜重威之子。947年杜重威拒绝调镇，送他到麻答处作人质以求援兵。生卒年未载。", "biography": null, "status": "draft", "id": "f5f27d6b-c724-5829-8b09-b9d5cb142bf1"}, {"name": "麻答", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领，《资治通鉴》称为耶律德光的从弟。944年二月由周儒引导从马家口渡河，攻郓州北津，以接应杨光远。个人其他名字及生卒年本批未核。", "biography": null, "status": "draft", "id": "5911d4cb-fa8a-51ff-a1e4-44450396116a"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "张琏（幽州军指挥使）", "aliases": ["張璉（幽州軍指揮使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年率领赵延寿留在恒州的幽州亲兵，杜重威请求借其军守魏州。是否与895年所见同名人物有关，未得确证，分别建档。生卒年未载。", "biography": null, "status": "draft", "id": "8b130b3f-0eba-556e-9baa-b43bd73ead49"}, {"name": "杨衮", "aliases": ["楊袞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领。947年麻答派他率契丹及幽州兵援杜重威；他出兵后，恒州留守军减少，为当地起兵提供时机。生卒年未载。", "biography": null, "status": "draft", "id": "4115ee92-89ee-534e-a312-a3e1bd4793d6"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "慕容彦超", "aliases": ["慕容彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋濮州刺史，原属吐谷浑，与刘知远同母。945年正月随皇甫遇侦察契丹军，在榆林店受围，与皇甫遇共同救回杜知敏，得到安审琦援军后返回相州。出生及死亡年本段未载。", "biography": null, "status": "draft", "id": "e0c11a24-a441-5d69-b8e3-b5bdc109357b"}, {"name": "杨邠", "aliases": ["楊邠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冠氏人，947年二月任河东都押牙，与郭威共同劝刘知远接受称帝建议。生卒年暂未录入。", "biography": null, "status": "draft", "id": "eede7986-584c-5c2a-9c1c-39a3959f1291"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "王章", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "魏州南乐人，曾任孔目官，随刘知远到太原。947年任权三司使。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "154bd412-f052-5459-9c17-951cfcd91759"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}, {"name": "和凝", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：和凝，翰林学士、建议者。", "biography": null, "status": "draft", "id": "f4084e8d-6018-5318-8498-525d067ebeda"}, {"name": "刘昫", "aliases": ["劉昫", "刘煦", "劉煦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘昫，端明殿学士、受相职者。", "biography": null, "status": "draft", "id": "b63eeed9-ecc3-575d-aba8-41b03e6caa3e"}, {"name": "薛怀让", "aliases": ["薛懷讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后晋怀州刺史。944年二月乙巳与李守贞、皇甫遇、梁汉璋等率合计一万军队沿河水陆进兵。生卒年本批未核。", "biography": null, "status": "draft", "id": "f1bb0fbd-9418-522b-b292-28446544ad7f"}, {"name": "郭从义", "aliases": ["郭從義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年任郑州防御使。六月刘知远令他先入大梁清理宫禁，并秘密命令他杀李从益与王淑妃。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1119f609-51af-51d0-9244-ca7ac5b42d47"}, {"name": "刘铎", "aliases": ["劉鐸"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年任马步都指挥使。安国节度使高奉明离镇前，请麻答安排刘铎为节度副使、主持军府事务。生卒年未载。", "biography": null, "status": "draft", "id": "c7572e9d-46d8-5572-a786-fee85988afdb"}, {"name": "杨安", "aliases": ["楊安"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领。947年受麻答派遣，与李殷率千骑进攻洺州，在邢、洺两州境内劫掠。生卒年未载。", "biography": null, "status": "draft", "id": "4a4a2ad5-d94e-50c2-91d3-454026e4b321"}, {"name": "李殷", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "蓟人，后晋义武节度使。946年六月受任北面行营步军都指挥使兼都排阵使。生卒年未载；与后周王殷分为不同主体。", "biography": null, "status": "draft", "id": "bfab47cb-1a5c-5497-982a-5bf911264b2b"}, {"name": "何福进", "aliases": ["何福進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：何福进，宿卫军校、力战者。", "biography": null, "status": "draft", "id": "9212470a-66f0-53db-8b65-ab0f833848be"}, {"name": "李筠（原名李荣）", "aliases": ["李榮（控鶴指揮使）", "李荣（控鹤指挥使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州太原人，初名荣，后来因避周世宗讳改名筠。947年任控鹤指挥使，与何福进筹划恒州起兵，先夺甲库并组织官兵与居民作战。与李昪的父亲李荣、晚唐同名李筠分别建档。生卒年尚未录入。", "biography": null, "status": "draft", "id": "5fa92315-29cb-56c6-9108-8f703de9861a"}, {"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}, {"name": "白再荣", "aliases": ["白再榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋护圣都指挥使。944年二月甲辰朔奉命驻守马家口。原地名与石赟所守麻家口分别保留，不自动混写。生卒年本批未核。", "biography": null, "status": "draft", "id": "91caa219-2e64-565f-b15f-a4402d8c7b3d"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "刘晞", "aliases": ["劉晞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "涿州人，在契丹曾任枢密使、同平章事及燕京留守。947年任西京留守，到洛阳后责斥奚王慢待赵在礼。与后晋官员刘昫字形、职务不同，暂不合并；生卒年未载。", "biography": null, "status": "draft", "id": "a5949823-5190-5e38-a780-eb04d4e680a5"}, {"name": "崔廷勋", "aliases": ["崔廷勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "河内人。947年正月《资治通鉴》称他为大同节度使兼侍中，耶律德光派他率兵看守迁到封禅寺的石重贵及家人。《旧五代史》称为蕃大将崔廷勋，未另建同名人；生卒年未载。", "biography": null, "status": "draft", "id": "43995ba6-a8ce-5d3a-86dd-43d3def50195"}, {"name": "郎五", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年正月耶律德光任命他为镇宁节度使。《资治通鉴》称其为族人，具体亲等未说明，不建立具体血缘关系；生卒年未载。", "biography": null, "status": "draft", "id": "e3f58742-cf58-5340-8710-12036d6edab3"}, {"name": "李彦从", "aliases": ["李彥從"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年任左飞龙使，恒州驱逐契丹驻军后，奉刘知远命率军前往增援。生卒年未载。", "biography": null, "status": "draft", "id": "36337a5b-3293-5487-ba5b-47ef5d6636d5"}, {"name": "王饶", "aliases": ["王饒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋奉国左厢都指挥使。946年十月辛未，石重贵任命他为北征军的步军右厢都指挥使。《旧五代史》卷85记有相同部署。生卒年及籍贯未载。", "biography": null, "status": "draft", "id": "0da0dd37-babc-548d-b33d-f587847464ed"}, {"name": "赵延乂", "aliases": ["趙延乂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：赵延乂，翰林天文、轮值者。", "biography": null, "status": "draft", "id": "6c04e553-0a04-5dbe-9236-85f04393f290"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
