ft", "id": "198d3323-9f14-5d7c-a840-9bc0e433a928", "subject_id": "f68cee59-1996-5d1f-b4ab-973162984608", "source_id": "0e8c5cbe-b3b5-5150-874d-9f7f18041aa1"}, {"subject_table": "event", "field_path": "description", "claim_text": "麻答等携家属财物退守北城，起兵队伍出现劫掠与逃散。", "citation": "卷287·天福十二年（947年七月至八月及追述）·zztj-v287-y0947-p039·原文件第44行", "note": "原文：诸将继至，烟火四起，鼓噪震地。麻荅等大惊，载宝货家属，走保北城。而汉兵无所统壹，贪狡者乘乱剽掠，懦者窜匿。；核对说明：军民缺统一及部分人劫掠、逃散按史述整理，不把所有参战军民都记为劫掠者。", "status": "draft", "id": "3b5ee295-dd23-5746-a572-f95d95cfc640", "subject_id": "89fac057-c8c3-5371-8a7c-e65b62c45505", "source_id": "6a26cc69-9fa5-5783-93b7-06d09e929731"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "947年闰七月辛巳", "citation": "卷287·天福十二年（947年七月至八月及追述）·zztj-v287-y0947-p039·原文件第44行", "note": "原文：诸将继至，烟火四起，鼓噪震地。麻荅等大惊，载宝货家属，走保北城。而汉兵无所统壹，贪狡者乘乱剽掠，懦者窜匿。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "7e822565-0667-5747-9c2a-296d2a6d5553", "subject_id": "89fac057-c8c3-5371-8a7c-e65b62c45505", "source_id": "6a26cc69-9fa5-5783-93b7-06d09e929731"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "麻答：惊慌后载财物家属退守北城。", "citation": "卷287·天福十二年（947年七月至八月及追述）·zztj-v287-y0947-p039·原文件第44行", "note": "原文：诸将继至，烟火四起，鼓噪震地。麻荅等大惊，载宝货家属，走保北城。而汉兵无所统壹，贪狡者乘乱剽掠，懦者窜匿。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "069edce6-0b36-5dca-a95e-964f31a305bb", "subject_id": "ed986a5b-1e3c-5321-9459-5d1a10746fb5", "source_id": "6a26cc69-9fa5-5783-93b7-06d09e929731"}, {"subject_table": "event", "field_path": "description", "claim_text": "契丹军从北门反攻，史书记汉民死者二千余。", "citation": "卷287·天福十二年（947年七月至八月及追述）·zztj-v287-y0947-p039·原文件第44行", "note": "原文：八月，壬午朔，契丹自北门入，势复振，汉民死者二千馀人。；核对说明：二千余是此阶段《资治通鉴》叙述，与后段李谷讲话中的近三千可能范围不同，不能相加或当精确单日清点。", "status": "draft", "id": "6d63e3c5-02a5-59e0-9bdb-87ea93766194", "subject_id": "4f34ecf4-b846-54fc-b07d-e0b2c7bba869", "source_id": "6a26cc69-9fa5-5783-93b7-06d09e929731"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "947年八月壬午朔", "citat